/// <reference path="../edge-runtime.d.ts" />
import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  getUserFromBearer,
  requireActiveOrg,
  requireTikTokContentPlatformConfigured,
  tiktokContentCorsHeaders,
  tiktokContentJson,
} from "../_shared/tiktokContentAuth.ts";
import {
  fetchAllTikTokBusinessVideos,
  fetchAllTikTokBusinessVideosInRange,
  fetchAllTikTokVideos,
  fetchAllTikTokVideosInRange,
  fetchTikTokUserInfo,
} from "../_shared/tiktokContentApi.ts";
import { pickTikTokAccountLabel } from "../_shared/tiktokContentAccountProfile.ts";
import { resolveOrgTikTokContentForMetrics } from "../_shared/tiktokContentOrgResolver.ts";
import {
  TIKTOK_CONTENT_OAUTH_TOKEN_KINDS,
} from "../_shared/tiktokContentAuth.ts";
import {
  backfillLinkVideoIds,
  buildPlanMatchIndex,
  computeEngagementRate,
  loadPlanDetails,
  loadTikTokPlanLinks,
  matchVideoToPlan,
} from "../_shared/tiktokContentPlanMatcher.ts";

const CACHE_TTL_MINUTES = 15;
const METRICS_CACHE_KEY = "video-list-v2";
const COMMENTS_INBOX_CACHE_KEY = "video-list-comments-inbox-v1";
const MAX_LOOKBACK_DAYS = 365;

function formatDateYmd(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function defaultDateRange(): { start: string; end: string } {
  const end = new Date();
  const start = new Date();
  start.setDate(start.getDate() - 29);
  return { start: formatDateYmd(start), end: formatDateYmd(end) };
}

function parseYmd(ymd: string): Date | null {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(ymd.trim());
  if (!m) return null;
  const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return Number.isNaN(d.getTime()) ? null : d;
}

function clampDateRange(startYmd: string, endYmd: string, now = new Date()) {
  const minStart = new Date(now);
  minStart.setDate(minStart.getDate() - MAX_LOOKBACK_DAYS);
  let start = parseYmd(startYmd) ?? minStart;
  let end = parseYmd(endYmd) ?? now;
  if (start.getTime() < minStart.getTime()) start = minStart;
  if (start.getTime() > end.getTime()) start = end;
  return { start: formatDateYmd(start), end: formatDateYmd(end) };
}

Deno.serve(async (req: Request) => {
  try {
    if (req.method === "OPTIONS") {
      return new Response("ok", { status: 200, headers: tiktokContentCorsHeaders });
    }
    if (req.method !== "POST") {
      return tiktokContentJson({ error: "Method not allowed" }, 405);
    }

    const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
    const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
    if (!supabaseUrl || !serviceRoleKey) {
      return tiktokContentJson({ error: "Server misconfigured" }, 500);
    }

    const platformForbidden = requireTikTokContentPlatformConfigured();
    if (platformForbidden) return platformForbidden;

    const admin = createClient(supabaseUrl, serviceRoleKey);
    const userRes = await getUserFromBearer(admin, req.headers.get("Authorization"));
    if ("error" in userRes) return userRes.error;

    let body: Record<string, unknown>;
    try {
      body = (await req.json()) as Record<string, unknown>;
    } catch {
      return tiktokContentJson({ error: "Invalid JSON body" }, 400);
    }

    const organizationId = String(body.organization_id ?? "").trim();
    if (!organizationId) return tiktokContentJson({ error: "Missing organization_id" }, 400);

    const orgForbidden = await requireActiveOrg(admin, userRes.userId, organizationId);
    if (orgForbidden) return orgForbidden;

    const inboxMode = body.inbox_mode === true;
    const now = new Date();
    const dr = defaultDateRange();
    const rawStart = String(body.date_start ?? dr.start).trim();
    const rawEnd = String(body.date_end ?? dr.end).trim();
    const clamped = clampDateRange(rawStart, rawEnd, now);
    const inboxCacheStart = formatDateYmd(
      (() => {
        const min = new Date(now);
        min.setDate(min.getDate() - MAX_LOOKBACK_DAYS);
        return min;
      })(),
    );
    const inboxCacheEnd = formatDateYmd(now);
    const dateStart = inboxMode ? inboxCacheStart : clamped.start;
    const dateEnd = inboxMode ? inboxCacheEnd : clamped.end;
    const metricsCacheKey = inboxMode ? COMMENTS_INBOX_CACHE_KEY : METRICS_CACHE_KEY;
    const openIdParam = body.open_id != null ? String(body.open_id).trim() : null;
    const forceRefresh = body.force_refresh === true;

    const resolved = await resolveOrgTikTokContentForMetrics(admin, organizationId, openIdParam);
    if (!resolved) {
      return tiktokContentJson({ error: "TikTok Content not connected or no account configured" }, 400);
    }

    const { accessToken, account, tokenKind } = resolved;
    const openId = account.open_id;

    if (!forceRefresh) {
      const { data: cached } = await admin
        .from("tiktok_content_metrics_cache")
        .select("response_json, fetched_at")
        .eq("organization_id", organizationId)
        .eq("open_id", openId)
        .eq("date_start", dateStart)
        .eq("date_end", dateEnd)
        .eq("metrics_key", metricsCacheKey)
        .eq("page_token", "")
        .gt("expires_at", now.toISOString())
        .maybeSingle();
      if (cached?.response_json) {
        return tiktokContentJson({ ...(cached.response_json as object), cached: true }, 200);
      }
    }

    let videos;
    let followerCount: number | null = null;
    try {
      const [fetchedVideos, userInfo] = await Promise.all([
        tokenKind === TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.ttUser
          ? inboxMode
            ? fetchAllTikTokBusinessVideos(accessToken, openId)
            : fetchAllTikTokBusinessVideosInRange(accessToken, openId, dateStart, dateEnd)
          : inboxMode
            ? fetchAllTikTokVideos(accessToken)
            : fetchAllTikTokVideosInRange(accessToken, dateStart, dateEnd),
        fetchTikTokUserInfo(accessToken).catch((e) => {
          console.warn("tiktok-content-metrics userInfo:", e instanceof Error ? e.message : e);
          return {};
        }),
      ]);
      videos = fetchedVideos;
      const fc = Number(userInfo.follower_count ?? NaN);
      followerCount = Number.isFinite(fc) ? fc : null;
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      console.error("tiktok-content-metrics fetchVideos:", msg);
      return tiktokContentJson({ error: msg, code: "TIKTOK_CONTENT_API_ERROR" }, 400);
    }

    const links = await loadTikTokPlanLinks(admin, organizationId);
    const matchIndex = buildPlanMatchIndex(links);
    const planIds = [...new Set(links.map((l) => l.social_media_plan_id))];
    const planMap = await loadPlanDetails(admin, planIds);

    const backfillMatches: Array<{ link_id: string; video_id: string }> = [];
    const rows = videos.map((video) => {
      const match = matchVideoToPlan(video, matchIndex, planMap);
      const videoId = String(video.id ?? "").trim();
      if (match.link_id && videoId && match.match_type) {
        backfillMatches.push({ link_id: match.link_id, video_id: videoId });
      }
      const engagementRate = computeEngagementRate(video);
      const createTime = Number(video.create_time ?? 0);
      const postedAt = Number.isFinite(createTime) && createTime > 0
        ? new Date(createTime * 1000).toISOString()
        : null;

      return {
        video_id: videoId,
        title: video.title ?? video.video_description ?? "",
        share_url: video.share_url ?? null,
        cover_image_url: video.cover_image_url ?? null,
        duration: video.duration ?? null,
        view_count: video.view_count ?? 0,
        like_count: video.like_count ?? 0,
        comment_count: video.comment_count ?? 0,
        share_count: video.share_count ?? 0,
        engagement_rate: engagementRate,
        posted_at: postedAt,
        plan_id: match.plan_id,
        service_name: match.service_name,
        content_pillar: match.content_pillar,
        pic_name: match.pic_name,
        plan_post_date: match.actual_post_date,
        match_type: match.match_type,
      };
    });

    if (backfillMatches.length > 0) {
      await backfillLinkVideoIds(admin, organizationId, openId, backfillMatches);
    }

    const summary = {
      video_count: rows.length,
      follower_count: followerCount,
      total_views: rows.reduce((s, r) => s + (Number(r.view_count) || 0), 0),
      total_likes: rows.reduce((s, r) => s + (Number(r.like_count) || 0), 0),
      total_comments: rows.reduce((s, r) => s + (Number(r.comment_count) || 0), 0),
      total_shares: rows.reduce((s, r) => s + (Number(r.share_count) || 0), 0),
      avg_engagement_rate: rows.length > 0
        ? rows.reduce((s, r) => s + (Number(r.engagement_rate) || 0), 0) / rows.length
        : null,
      matched_plans: rows.filter((r) => r.plan_id).length,
    };

    const payload = {
      rows,
      summary,
      open_id: openId,
      account_id: account.id,
      account_label: pickTikTokAccountLabel(account),
      date_start: dateStart,
      date_end: dateEnd,
      inbox_mode: inboxMode,
      fetched_at: now.toISOString(),
    };

    const expiresAt = new Date(now.getTime() + CACHE_TTL_MINUTES * 60_000).toISOString();
    await admin.from("tiktok_content_metrics_cache").upsert({
      organization_id: organizationId,
      open_id: openId,
      date_start: dateStart,
      date_end: dateEnd,
      metrics_key: metricsCacheKey,
      page_token: "",
      response_json: payload,
      fetched_at: now.toISOString(),
      expires_at: expiresAt,
    }, {
      onConflict: "organization_id,open_id,date_start,date_end,metrics_key,page_token",
    });

    return tiktokContentJson(payload, 200);
  } catch (unhandled) {
    const msg = unhandled instanceof Error ? unhandled.message : String(unhandled);
    console.error("tiktok-content-metrics unhandled:", msg);
    return tiktokContentJson({ error: msg, code: "INTERNAL_ERROR" }, 500);
  }
});

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export const tiktokContentCorsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

export const TIKTOK_CONTENT_API_BASE = "https://open.tiktokapis.com/v2";
export const TIKTOK_BUSINESS_API_BASE = "https://business-api.tiktok.com/open_api/v1.3";
export const TIKTOK_CONTENT_OAUTH_SCOPES =
  "user.info.basic,video.list,user.info.stats,comment.list,comment.list.manage,video.upload,video.publish";

export const TIKTOK_CONTENT_PUBLISH_SCOPES = ["video.upload", "video.publish"] as const;

/** Login Kit / Direct Post (developers.tiktok.com) — separate from business-api CONTENT credentials. */
export const TIKTOK_CONTENT_PUBLISH_OAUTH_SCOPES =
  "user.info.basic,video.upload,video.publish";

export type TikTokContentOAuthTokenKind = "login_kit" | "tt_user";

export const TIKTOK_CONTENT_OAUTH_TOKEN_KINDS = {
  loginKit: "login_kit" as TikTokContentOAuthTokenKind,
  ttUser: "tt_user" as TikTokContentOAuthTokenKind,
};

export const TIKTOK_CONTENT_COMMENT_SCOPES = ["comment.list", "comment.list.manage"] as const;

/** Union comma-separated OAuth scope strings (deduped, stable order). */
export function mergeTikTokContentOAuthScopes(
  ...scopeStrings: (string | null | undefined)[]
): string {
  const merged = new Set<string>();
  for (const raw of scopeStrings) {
    for (const part of String(raw ?? "").split(",")) {
      const trimmed = part.trim();
      if (trimmed) merged.add(trimmed);
    }
  }
  return [...merged].join(",");
}

/** TikTok often omits scopes in token JSON; merge stored + requested scopes. */
export function resolveTikTokContentOAuthScopes(stored: string | null | undefined): string {
  return mergeTikTokContentOAuthScopes(stored, TIKTOK_CONTENT_OAUTH_SCOPES);
}

export function tiktokContentScopesIncludeComments(scope: string | null | undefined): boolean {
  const parts = String(scope ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  return TIKTOK_CONTENT_COMMENT_SCOPES.every((required) => parts.includes(required));
}

export function tiktokContentScopesIncludePublish(scope: string | null | undefined): boolean {
  const parts = String(scope ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  return TIKTOK_CONTENT_PUBLISH_SCOPES.every((required) => parts.includes(required));
}

export function tiktokContentJson(body: object, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...tiktokContentCorsHeaders, "Content-Type": "application/json" },
  });
}

export function readPlatformTikTokContentOAuth(): { clientKey: string; clientSecret: string } | null {
  const clientKey = Deno.env.get("TIKTOK_CONTENT_CLIENT_KEY")?.trim() ??
    Deno.env.get("TIKTOK_CONTENT_APP_ID")?.trim() ?? "";
  const clientSecret = Deno.env.get("TIKTOK_CONTENT_CLIENT_SECRET")?.trim() ??
    Deno.env.get("TIKTOK_CONTENT_APP_SECRET")?.trim() ?? "";
  if (!clientKey || !clientSecret) return null;
  return { clientKey, clientSecret };
}

/** developers.tiktok.com app — Login Kit token exchange & publish OAuth start. */
export function readPlatformTikTokContentPublishOAuth(): { clientKey: string; clientSecret: string } | null {
  const clientKey = Deno.env.get("TIKTOK_CONTENT_PUBLISH_CLIENT_KEY")?.trim() ??
    Deno.env.get("TIKTOK_DEVELOPERS_CLIENT_KEY")?.trim() ?? "";
  const clientSecret = Deno.env.get("TIKTOK_CONTENT_PUBLISH_CLIENT_SECRET")?.trim() ??
    Deno.env.get("TIKTOK_DEVELOPERS_CLIENT_SECRET")?.trim() ?? "";
  if (!clientKey || !clientSecret) return null;
  return { clientKey, clientSecret };
}

export function isTikTokContentPlatformConfigured(): boolean {
  return readPlatformTikTokContentOAuth() !== null;
}

export function isTikTokContentPublishPlatformConfigured(): boolean {
  return readPlatformTikTokContentPublishOAuth() !== null;
}

export function requireTikTokContentPlatformConfigured(): Response | null {
  if (!isTikTokContentPlatformConfigured()) {
    return tiktokContentJson(
      {
        error:
          "TikTok Content is not configured. Set TIKTOK_CONTENT_CLIENT_KEY and TIKTOK_CONTENT_CLIENT_SECRET in Supabase Edge Function secrets.",
      },
      503,
    );
  }
  return null;
}

export function requireTikTokContentPublishPlatformConfigured(): Response | null {
  if (!isTikTokContentPublishPlatformConfigured()) {
    return tiktokContentJson(
      {
        error:
          "TikTok publish is not configured. Set TIKTOK_CONTENT_PUBLISH_CLIENT_KEY and TIKTOK_CONTENT_PUBLISH_CLIENT_SECRET (developers.tiktok.com app) in Supabase Edge Function secrets.",
      },
      503,
    );
  }
  return null;
}

export function tiktokContentOAuthRedirectUri(): string {
  const explicit = Deno.env.get("TIKTOK_CONTENT_OAUTH_REDIRECT_URI")?.trim();
  if (explicit) return explicit;
  const supabaseUrl = (Deno.env.get("SUPABASE_URL") ?? "").replace(/\/+$/, "");
  return `${supabaseUrl}/functions/v1/tiktok-content-oauth-callback`;
}

export function appPublicOrigin(): string {
  const raw =
    Deno.env.get("APP_PUBLIC_URL")?.trim() ??
    Deno.env.get("SYNCKERJA_APP_URL")?.trim() ??
    "";
  return raw.replace(/\/+$/, "");
}

export const TIKTOK_CONTENT_OAUTH_RETURN_PATHS = new Set([
  "/digital-marketing/social-media-performance/tiktok/settings",
  "/digital-marketing/social-media-performance/manage-comments/tiktok/settings",
]);

export async function getUserFromBearer(
  admin: SupabaseClient,
  authHeader: string | null,
): Promise<{ userId: string } | { error: Response }> {
  const token = authHeader?.startsWith("Bearer ") ? authHeader.slice("Bearer ".length).trim() : "";
  if (!token) return { error: tiktokContentJson({ error: "Unauthorized" }, 401) };
  const { data: userRes, error: userErr } = await admin.auth.getUser(token);
  if (userErr || !userRes?.user?.id) {
    return { error: tiktokContentJson({ error: "Invalid token" }, 401) };
  }
  return { userId: userRes.user.id };
}

export async function isOmnichannelContentAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<boolean> {
  const { data: owner } = await admin
    .from("user_roles")
    .select("id")
    .eq("user_id", userId)
    .eq("organization_id", organizationId)
    .eq("role", "owner")
    .maybeSingle();
  if (owner) return true;

  const { data: staffRows } = await admin
    .from("organization_omnichannel_staff")
    .select("employee_id, employees!inner(user_id)")
    .eq("organization_id", organizationId)
    .eq("role", "admin");

  for (const row of staffRows ?? []) {
    const emp = row as { employees?: { user_id?: string } | { user_id?: string }[] };
    const employees = emp.employees;
    const userIds: string[] = [];
    if (Array.isArray(employees)) {
      for (const e of employees) {
        if (e?.user_id) userIds.push(String(e.user_id));
      }
    } else if (employees && typeof employees === "object" && "user_id" in employees) {
      const uid = (employees as { user_id?: string }).user_id;
      if (uid) userIds.push(String(uid));
    }
    if (userIds.includes(userId)) return true;
  }
  return false;
}

export async function requireOrgAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const ok = await isOmnichannelContentAdmin(admin, userId, organizationId);
  if (!ok) return tiktokContentJson({ error: "Forbidden" }, 403);
  return null;
}

export async function requireActiveOrg(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const { data: profile } = await admin
    .from("profiles")
    .select("active_organization_id")
    .eq("user_id", userId)
    .maybeSingle();
  const activeOrg = profile?.active_organization_id != null ? String(profile.active_organization_id) : "";
  if (!activeOrg || activeOrg !== organizationId) {
    return tiktokContentJson({ error: "Forbidden" }, 403);
  }
  return null;
}

import {
  TIKTOK_BUSINESS_API_BASE,
  TIKTOK_CONTENT_API_BASE,
  TIKTOK_CONTENT_OAUTH_TOKEN_KINDS,
  type TikTokContentOAuthTokenKind,
} from "./tiktokContentAuth.ts";
import { normalizeTikTokCaptionFromApi } from "./formatTikTokCaption.ts";

export const VIDEO_LIST_FIELDS = [
  "id",
  "title",
  "create_time",
  "share_url",
  "cover_image_url",
  "view_count",
  "like_count",
  "comment_count",
  "share_count",
  "video_description",
  "duration",
].join(",");

export const USER_INFO_FIELDS = [
  "open_id",
  "display_name",
  "avatar_url",
  "follower_count",
  "following_count",
  "likes_count",
  "video_count",
].join(",");

type TikTokContentError = {
  code?: string;
  message?: string;
  log_id?: string;
};

type TikTokContentEnvelope<T> = {
  data?: T;
  error?: TikTokContentError;
};

export type TikTokVideoRow = {
  id?: string;
  title?: string;
  create_time?: number;
  share_url?: string;
  cover_image_url?: string;
  view_count?: number;
  like_count?: number;
  comment_count?: number;
  share_count?: number;
  video_description?: string;
  duration?: number;
};

export type TikTokUserInfo = {
  open_id?: string;
  display_name?: string;
  avatar_url?: string;
  follower_count?: number;
  following_count?: number;
  likes_count?: number;
  video_count?: number;
};

function throwApiError(prefix: string, err?: TikTokContentError, httpStatus?: number): never {
  const code = err?.code?.trim() ?? "";
  const msg = err?.message?.trim() ?? "";
  const logId = err?.log_id?.trim();
  const logSuffix = logId ? ` [log_id=${logId}]` : "";
  const detail = msg && msg !== "ok" && msg !== "OK"
    ? `${prefix}: ${msg}${code && code !== "ok" ? ` (${code})` : ""}${logSuffix}`
    : code && code !== "ok"
      ? `${prefix} (${code})${logSuffix}`
      : httpStatus
        ? `${prefix} HTTP ${httpStatus}${logSuffix}`
        : `${prefix}${logSuffix}`;
  throw new Error(detail);
}

type TikTokOAuthTokenPayload = {
  access_token?: string;
  refresh_token?: string;
  open_id?: string;
  scope?: string;
  expires_in?: number;
  refresh_expires_in?: number;
};


export type TikTokCommentApiRow = {
  id?: string;
  video_id?: string;
  text?: string;
  like_count?: number;
  reply_count?: number;
  parent_comment_id?: string | null;
  create_time?: number;
  display_name?: string;
};

type TikTokOAuthTokenErrorBody = {
  error?: string | TikTokContentError;
  error_description?: string;
  log_id?: string;
  data?: TikTokOAuthTokenPayload;
} & TikTokOAuthTokenPayload;

function parseTikTokOAuthTokenResponse(json: TikTokOAuthTokenErrorBody): TikTokOAuthTokenPayload {
  const payload = (json.data ?? json) as TikTokOAuthTokenPayload;
  return payload;
}

/** TikTok often omits scope in token JSON; read every known location. */
export function parseOAuthScopeFromTokenJson(json: TikTokOAuthTokenErrorBody): string | undefined {
  const payload = parseTikTokOAuthTokenResponse(json);
  const candidates = [
    payload.scope,
    typeof json.scope === "string" ? json.scope : undefined,
    json.data && typeof json.data === "object" && "scope" in json.data
      ? String((json.data as { scope?: unknown }).scope ?? "")
      : undefined,
  ];
  for (const raw of candidates) {
    const trimmed = String(raw ?? "").trim();
    if (trimmed) return trimmed;
  }
  return undefined;
}

function throwTikTokOAuthTokenError(
  prefix: string,
  json: TikTokOAuthTokenErrorBody,
  httpStatus: number,
): never {
  if (typeof json.error === "string" && json.error.trim()) {
    const desc = json.error_description?.trim();
    throw new Error(desc || json.error.trim());
  }
  if (json.error && typeof json.error === "object") {
    throwApiError(prefix, json.error, httpStatus);
  }
  throwApiError(prefix, undefined, httpStatus);
}

export async function exchangeTikTokContentAuthCode(
  clientKey: string,
  clientSecret: string,
  code: string,
  redirectUri: string,
): Promise<{
  access_token: string;
  refresh_token: string;
  open_id: string;
  scope?: string;
  expires_in?: number;
  refresh_expires_in?: number;
}> {
  const decodedCode = decodeURIComponent(code);
  const body = new URLSearchParams({
    client_key: clientKey,
    client_secret: clientSecret,
    code: decodedCode,
    grant_type: "authorization_code",
    redirect_uri: redirectUri,
  });
  const res = await fetch(`${TIKTOK_CONTENT_API_BASE}/oauth/token/`, {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      "Cache-Control": "no-cache",
    },
    body: body.toString(),
  });
  const json = await res.json().catch(() => ({})) as TikTokOAuthTokenErrorBody;
  const payload = parseTikTokOAuthTokenResponse(json);
  const accessToken = payload.access_token?.trim() ?? "";
  const refreshToken = payload.refresh_token?.trim() ?? "";
  const openId = payload.open_id?.trim() ?? "";

  const envelopeErr =
    json.error && typeof json.error === "object" ? json.error : undefined;
  const envelopeFailed = envelopeErr != null && envelopeErr.code !== "ok";

  if (!res.ok || envelopeFailed || !accessToken || !openId) {
    throwTikTokOAuthTokenError("token_exchange_failed", json, res.status);
  }

  const scopeParsed = parseOAuthScopeFromTokenJson(json);

  return {
    access_token: accessToken,
    refresh_token: refreshToken || accessToken,
    open_id: openId,
    scope: scopeParsed,
    expires_in: payload.expires_in,
    refresh_expires_in: payload.refresh_expires_in,
  };
}

export async function refreshTikTokContentAccessToken(
  clientKey: string,
  clientSecret: string,
  refreshToken: string,
): Promise<{
  access_token: string;
  refresh_token?: string;
  open_id?: string;
  scope?: string;
  expires_in?: number;
} | null> {
  const body = new URLSearchParams({
    client_key: clientKey,
    client_secret: clientSecret,
    grant_type: "refresh_token",
    refresh_token: refreshToken,
  });
  const res = await fetch(`${TIKTOK_CONTENT_API_BASE}/oauth/token/`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: body.toString(),
  });
  const json = await res.json().catch(() => ({})) as TikTokOAuthTokenErrorBody;
  const payload = parseTikTokOAuthTokenResponse(json);
  const accessToken = payload.access_token?.trim() ?? "";
  const envelopeErr =
    json.error && typeof json.error === "object" ? json.error : undefined;
  const envelopeFailed = envelopeErr != null && envelopeErr.code !== "ok";
  if (!res.ok || envelopeFailed || !accessToken) {
    const errMsg =
      typeof json.error === "string"
        ? json.error_description ?? json.error
        : envelopeErr?.message ?? String(res.status);
    console.error("tiktok content refresh:", errMsg);
    return null;
  }
  return {
    access_token: accessToken,
    refresh_token: payload.refresh_token?.trim() || undefined,
    open_id: payload.open_id?.trim() || undefined,
    scope: parseOAuthScopeFromTokenJson(json),
    expires_in: payload.expires_in,
  };
}

type TikTokBusinessOAuthTokenData = {
  access_token?: string;
  refresh_token?: string;
  open_id?: string;
  creator_id?: string;
  scope?: string;
  expires_in?: number;
  refresh_token_expires_in?: number;
  access_token_expires_in?: number;
};

function parseTikTokBusinessOAuthTokenResponse(
  json: { data?: TikTokBusinessOAuthTokenData },
): TikTokBusinessOAuthTokenData {
  return json.data ?? {};
}

type TikTokBusinessTokenExchangeResponse = {
  code?: number;
  message?: string;
  data?: TikTokBusinessOAuthTokenData;
};

function parseBusinessTokenExchangeResult(
  json: TikTokBusinessTokenExchangeResponse,
): {
  access_token: string;
  refresh_token: string;
  open_id: string;
  scope?: string;
  expires_in?: number;
  refresh_expires_in?: number;
} | null {
  const payload = json.data ?? {};
  const accessToken = payload.access_token?.trim() ?? "";
  const refreshToken = payload.refresh_token?.trim() ?? "";
  const openId = payload.open_id?.trim() ?? payload.creator_id?.trim() ?? "";
  if (json.code !== 0 || !accessToken || !openId) return null;
  return {
    access_token: accessToken,
    refresh_token: refreshToken || accessToken,
    open_id: openId,
    scope: payload.scope?.trim() || undefined,
    expires_in: payload.expires_in ?? payload.access_token_expires_in,
    refresh_expires_in: payload.refresh_token_expires_in,
  };
}

/** TikTok Business Organic (tt_user) — required for account comment API. */
export async function exchangeTikTokBusinessOrganicAuthCode(
  appId: string,
  appSecret: string,
  authCode: string,
  redirectUri?: string,
): Promise<{
  access_token: string;
  refresh_token: string;
  open_id: string;
  scope?: string;
  expires_in?: number;
  refresh_expires_in?: number;
}> {
  const code = authCode.trim();
  const redirect = redirectUri?.trim() ?? "";
  if (!code) throw new Error("token_exchange_failed: missing auth_code");
  if (!redirect) throw new Error("token_exchange_failed: missing redirect_uri");

  // Account-holder flow: v2 authorize → tt_user/oauth2/token (not portal/auth + creator_token).
  // Single request — auth codes are single-use and expire in seconds.
  const body = {
    client_id: appId,
    client_secret: appSecret,
    grant_type: "authorization_code",
    auth_code: code,
    redirect_uri: redirect,
  };

  const res = await fetch(`${TIKTOK_BUSINESS_API_BASE}/tt_user/oauth2/token/`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  const json = await res.json().catch(() => ({})) as TikTokBusinessTokenExchangeResponse;
  const parsed = parseBusinessTokenExchangeResult(json);
  if (parsed) return parsed;

  const msg = json.message?.trim() || `HTTP ${res.status}`;
  const codeSuffix = json.code != null ? ` (code ${json.code})` : "";
  if (json.code === 40131) {
    throw new Error(
      `token_exchange_failed: ${msg}${codeSuffix}. Start Connect again from settings — do not refresh the callback URL.`,
    );
  }
  throw new Error(`token_exchange_failed: ${msg}${codeSuffix}`);
}

export async function refreshTikTokBusinessOrganicAccessToken(
  appId: string,
  appSecret: string,
  refreshToken: string,
): Promise<{
  access_token: string;
  refresh_token?: string;
  open_id?: string;
  expires_in?: number;
} | null> {
  const res = await fetch(`${TIKTOK_BUSINESS_API_BASE}/tt_user/oauth2/refresh_token/`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      client_id: appId,
      client_secret: appSecret,
      grant_type: "refresh_token",
      refresh_token: refreshToken,
    }),
  });
  const json = await res.json().catch(() => ({})) as TikTokBusinessApiResponse<TikTokBusinessOAuthTokenData>;
  const payload = parseTikTokBusinessOAuthTokenResponse(json);
  const accessToken = payload.access_token?.trim() ?? "";
  if (!res.ok || json.code !== 0 || !accessToken) {
    console.error("tiktok business organic refresh:", json.message ?? res.status);
    return null;
  }
  return {
    access_token: accessToken,
    refresh_token: payload.refresh_token?.trim() || undefined,
    open_id: payload.open_id?.trim() || undefined,
    expires_in: payload.expires_in ?? payload.access_token_expires_in,
  };
}

