async function loginKitCommentPost(
  accessToken: string,
  path: string,
  body: Record<string, unknown>,
): Promise<void> {
  const url = `${TIKTOK_CONTENT_API_BASE}${path}`;
  const res = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  });
  const text = await res.text();
  const json = text
    ? parseTikTokBusinessJsonResponse(text) as TikTokContentEnvelope<Record<string, never>>
    : ({} as TikTokContentEnvelope<Record<string, never>>);
  if (!res.ok || json.error?.code !== "ok") {
    throwApiError(`login_kit${path}`, json.error, res.status);
  }
}

function formatBusinessCommentDeleteError(err: unknown): string {
  const base = err instanceof Error ? err.message : String(err);
  const lower = base.toLowerCase();
  if (
    lower.includes("40002")
    || lower.includes("invalid_params")
    || lower.includes("comment_id")
  ) {
    return (
      "Komentar ini tidak bisa dihapus di TikTok. "
      + "Hanya balasan/komentar dari akun Anda yang bisa dihapus — gunakan Hide untuk komentar pengguna lain."
    );
  }
  return base;
}

const TIKTOK_COMMENT_REPLY_MAX_LENGTH = 150;

function normalizeTikTokCommentReplyText(text: string): string {
  const trimmed = text.trim();
  if (!trimmed) throw new Error("Reply text is required");
  if (trimmed.length > TIKTOK_COMMENT_REPLY_MAX_LENGTH) {
    throw new Error(`Reply must be at most ${TIKTOK_COMMENT_REPLY_MAX_LENGTH} characters`);
  }
  return trimmed;
}

export async function replyTikTokComment(
  accessToken: string,
  args: { businessId: string; videoId: string; text: string; commentId: string },
  tokenKind: TikTokContentOAuthTokenKind = TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.loginKit,
): Promise<{ comment_id?: string }> {
  const parentCommentId = args.commentId.trim();
  const videoId = args.videoId.trim();
  if (!parentCommentId) throw new Error("comment_id is required to reply");
  if (!videoId) throw new Error("video_id is required to reply");

  const replyText = normalizeTikTokCommentReplyText(args.text);
  const businessBody: Record<string, unknown> = {
    business_id: args.businessId,
    account_id: videoId,
    video_id: videoId,
    comment_id: parentCommentId,
    text: replyText,
  };

  try {
    const data = await tiktokBusinessPost<{
      comment_id?: string | number;
      reply_id?: string | number;
    }>(
      accessToken,
      "/business/comment/reply/create/",
      businessBody,
    );
    const replyId = pickBusinessSnowflakeId(data.reply_id, data.comment_id);
    return {
      comment_id: replyId || undefined,
    };
  } catch (e) {
    throw enhanceBusinessCommentError(e, tokenKind);
  }
}

function normalizeBusinessCommentId(commentId: string): string {
  const trimmed = commentId.trim();
  if (!trimmed) return trimmed;
  if (!/^\d{10,}$/.test(trimmed)) {
    throw new Error(
      `comment_id format is invalid (${trimmed}). Refresh the page to reload comments and try again.`,
    );
  }
  return trimmed;
}

function isRetryableBusinessCommentParamError(message: string): boolean {
  const lower = message.toLowerCase();
  return (
    lower.includes("40002")
    || lower.includes("invalid")
    || lower.includes("validate your param")
  );
}

async function postBusinessCommentActionWithFallbacks(
  accessToken: string,
  path: string,
  attempts: Record<string, unknown>[],
): Promise<void> {
  const errors: string[] = [];
  for (const body of attempts) {
    try {
      await tiktokBusinessPost<Record<string, never>>(accessToken, path, body);
      return;
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      errors.push(msg);
      if (!isRetryableBusinessCommentParamError(msg)) {
        throw e;
      }
    }
  }
  throw new Error(errors[errors.length - 1] ?? `${path}: request failed`);
}

export async function deleteTikTokComment(
  accessToken: string,
  args: {
    businessId: string;
    videoId?: string;
    commentId: string;
    parentCommentId?: string;
  },
  tokenKind: TikTokContentOAuthTokenKind = TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.loginKit,
): Promise<void> {
  const commentId = normalizeBusinessCommentId(args.commentId);
  if (!commentId) throw new Error("comment_id is required to delete");
  const videoId = args.videoId?.trim() ?? "";
  const parentCommentId = args.parentCommentId?.trim() ?? "";

  const attempts: Record<string, unknown>[] = [
    { business_id: args.businessId, comment_id: commentId },
  ];
  if (videoId) {
    attempts.push(
      { business_id: args.businessId, video_id: videoId, comment_id: commentId },
      { business_id: args.businessId, item_id: videoId, comment_id: commentId },
      {
        business_id: args.businessId,
        account_id: videoId,
        video_id: videoId,
        comment_id: commentId,
      },
    );
    if (parentCommentId) {
      attempts.push({
        business_id: args.businessId,
        video_id: videoId,
        comment_id: commentId,
        parent_comment_id: parentCommentId,
      });
    }
  }

  try {
    await postBusinessCommentActionWithFallbacks(
      accessToken,
      "/business/comment/delete/",
      attempts,
    );
  } catch (e) {
    throw new Error(formatBusinessCommentDeleteError(e));
  }
}

export async function hideTikTokComment(
  accessToken: string,
  args: { businessId: string; commentId: string; videoId: string },
  tokenKind: TikTokContentOAuthTokenKind = TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.loginKit,
): Promise<void> {
  const commentId = normalizeBusinessCommentId(args.commentId);
  const videoId = args.videoId.trim();
  if (!commentId || !videoId) throw new Error("comment_id and video_id are required to hide");

  const attempts: Record<string, unknown>[] = [
    {
      business_id: args.businessId,
      video_id: videoId,
      comment_id: commentId,
      action: "HIDE",
    },
    {
      business_id: args.businessId,
      item_id: videoId,
      comment_id: commentId,
      action: "HIDE",
    },
  ];

  try {
    await postBusinessCommentActionWithFallbacks(
      accessToken,
      "/business/comment/hide/",
      attempts,
    );
  } catch (e) {
    throw enhanceBusinessCommentError(e, tokenKind);
  }
}

export async function likeTikTokComment(
  accessToken: string,
  args: { businessId: string; commentId: string; action?: "LIKE" | "UNLIKE" },
  tokenKind: TikTokContentOAuthTokenKind = TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.loginKit,
): Promise<void> {
  const commentId = normalizeBusinessCommentId(args.commentId);
  if (!commentId) throw new Error("comment_id is required to like");
  const action = args.action === "UNLIKE" ? "UNLIKE" : "LIKE";

  try {
    await tiktokBusinessPost<Record<string, never>>(
      accessToken,
      "/business/comment/like/",
      {
        business_id: args.businessId,
        comment_id: commentId,
        action,
      },
    );
  } catch (e) {
    throw enhanceBusinessCommentError(e, tokenKind);
  }
}

/** Keep in sync with src/6-0-social-media-manage-comments/lib/formatTikTokCaption.ts */
export function formatTikTokCaptionForDisplay(text: string): string {
  if (!text) return "";

  return text
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/\u2028/g, "\n")
    .replace(/\u2029/g, "\n\n")
    .replace(/\\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]+\n/g, "\n")
    .trim();
}

export function normalizeTikTokCaptionFromApi(caption?: string): string | undefined {
  if (!caption?.trim()) return undefined;
  return formatTikTokCaptionForDisplay(caption);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { fetchTikTokUserInfo } from "./tiktokContentApi.ts";
import { getTikTokContentAccessToken } from "./tiktokContentOrgResolver.ts";

type AccountRow = {
  id: string;
  open_id: string;
  label: string;
  display_name: string | null;
  avatar_url?: string | null;
  is_active: boolean;
};

/** Labels generated before we fetched TikTok profile (open_id fragment). */
export function isPlaceholderTikTokAccountLabel(
  label: string | null | undefined,
  openId: string,
): boolean {
  const trimmed = label?.trim() ?? "";
  if (!trimmed) return true;
  if (trimmed === openId) return true;
  if (/^TikTok\s+-?[\w]{4,16}$/i.test(trimmed)) return true;
  const idPrefix = openId.replace(/^-/, "").slice(0, 8);
  if (idPrefix && trimmed.toLowerCase().includes(idPrefix.toLowerCase())) return true;
  return false;
}

export function pickTikTokAccountLabel(account: {
  label?: string | null;
  display_name?: string | null;
  open_id: string;
}): string {
  for (const raw of [account.display_name, account.label]) {
    const name = raw?.trim() ?? "";
    if (name && !isPlaceholderTikTokAccountLabel(name, account.open_id)) return name;
  }
  return account.display_name?.trim() || account.label?.trim() || "TikTok";
}

export async function fetchTikTokAccountProfileFromApi(
  accessToken: string,
): Promise<{ displayName: string | null; avatarUrl: string | null } | null> {
  try {
    const user = await fetchTikTokUserInfo(accessToken);
    return {
      displayName: user.display_name?.trim() || null,
      avatarUrl: user.avatar_url?.trim() || null,
    };
  } catch (e) {
    console.warn("fetchTikTokAccountProfileFromApi:", e instanceof Error ? e.message : e);
    return null;
  }
}

function isTikTokHostedAvatarUrl(url: string | null | undefined): boolean {
  const u = url?.trim().toLowerCase() ?? "";
  if (!u) return false;
  return (
    u.includes("tiktokcdn")
    || u.includes("tiktokv.com")
    || u.includes("muscdn.com")
    || u.includes("byteoversea.com")
  );
}

export async function syncTikTokContentAccountProfiles(
  admin: SupabaseClient,
  organizationId: string,
  accounts: AccountRow[],
): Promise<number> {
  let updated = 0;
  const now = new Date().toISOString();

  for (const acc of accounts) {
    if (!acc.is_active) continue;
    const needsLabelSync = isPlaceholderTikTokAccountLabel(acc.label, acc.open_id)
      || isPlaceholderTikTokAccountLabel(acc.display_name, acc.open_id);
    const needsAvatarSync = !acc.avatar_url?.trim() || isTikTokHostedAvatarUrl(acc.avatar_url);
    if (!needsLabelSync && !needsAvatarSync) continue;

    const tokenResult = await getTikTokContentAccessToken(admin, organizationId, acc.open_id);
    if (!tokenResult) continue;

    const profile = await fetchTikTokAccountProfileFromApi(tokenResult.accessToken);
    if (!profile) continue;
    if (!needsLabelSync && !profile.avatarUrl) continue;

    const updatePayload: Record<string, string | null> = { updated_at: now };
    if (needsLabelSync && profile.displayName) {
      updatePayload.label = profile.displayName;
      updatePayload.display_name = profile.displayName;
    }
    if (needsAvatarSync && profile.avatarUrl) {
      updatePayload.avatar_url = profile.avatarUrl;
    }
    if (Object.keys(updatePayload).length <= 1) continue;

    const { error } = await admin
      .from("organization_tiktok_content_accounts")
      .update(updatePayload)
      .eq("id", acc.id)
      .eq("organization_id", organizationId);

    if (!error) updated += 1;
  }

  return updated;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  decryptTikTokContentToken,
  encryptTikTokContentToken,
} from "./tiktokContentConfigCrypto.ts";
import {
  mergeTikTokContentOAuthScopes,
  readPlatformTikTokContentOAuth,
  readPlatformTikTokContentPublishOAuth,
  TIKTOK_CONTENT_OAUTH_SCOPES,
  TIKTOK_CONTENT_OAUTH_TOKEN_KINDS,
  type TikTokContentOAuthTokenKind,
} from "./tiktokContentAuth.ts";
import {
  refreshTikTokBusinessOrganicAccessToken,
  refreshTikTokContentAccessToken,
} from "./tiktokContentApi.ts";

export type TikTokContentAccountRow = {
  id: string;
  organization_id: string;
  open_id: string;
  label: string;
  display_name: string | null;
  avatar_url: string | null;
  is_default: boolean;
  is_active: boolean;
  sort_order: number;
};

type TokenRow = {
  access_token_enc: string;
  refresh_token_enc: string;
  access_token_expires_at: string | null;
  oauth_scopes: string | null;
  oauth_token_kind: string | null;
  publish_access_token_enc?: string | null;
  publish_refresh_token_enc?: string | null;
  publish_access_token_expires_at?: string | null;
  publish_oauth_scopes?: string | null;
};

function normalizeTokenKind(raw: string | null | undefined): TikTokContentOAuthTokenKind {
  return raw === TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.ttUser
    ? TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.ttUser
    : TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.loginKit;
}

export async function getTikTokContentAccessToken(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
): Promise<{ accessToken: string; tokenKind: TikTokContentOAuthTokenKind } | null> {
  const { data: row } = await admin
    .from("organization_tiktok_content_connection_tokens")
    .select("access_token_enc, refresh_token_enc, access_token_expires_at, oauth_scopes, oauth_token_kind")
    .eq("organization_id", organizationId)
    .eq("open_id", openId)
    .maybeSingle();
  if (!row?.access_token_enc || !row?.refresh_token_enc) return null;

  const tokenRow = row as TokenRow;
  const tokenKind = normalizeTokenKind(tokenRow.oauth_token_kind);
  const expiresAtMs = tokenRow.access_token_expires_at
    ? new Date(String(tokenRow.access_token_expires_at)).getTime()
    : null;
  const needsRefresh = expiresAtMs != null &&
    Number.isFinite(expiresAtMs) &&
    expiresAtMs < Date.now() + 60_000;

  if (!needsRefresh) {
    try {
      const accessToken = await decryptTikTokContentToken(String(tokenRow.access_token_enc));
      return { accessToken, tokenKind };
    } catch (e) {
      console.error("getTikTokContentAccessToken decrypt:", e);
    }
  }

  let refreshToken: string;
  try {
    refreshToken = await decryptTikTokContentToken(String(tokenRow.refresh_token_enc));
  } catch (e) {
    console.error("getTikTokContentAccessToken refresh decrypt:", e);
    return null;
  }

  const oauth = readPlatformTikTokContentOAuth();
  const refreshed = oauth
    ? tokenKind === TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.ttUser
      ? await refreshTikTokBusinessOrganicAccessToken(
        oauth.clientKey,
        oauth.clientSecret,
        refreshToken,
      )
      : await refreshTikTokContentAccessToken(oauth.clientKey, oauth.clientSecret, refreshToken)
    : null;

  if (!refreshed?.access_token) {
    try {
      const accessToken = await decryptTikTokContentToken(String(tokenRow.access_token_enc));
      return { accessToken, tokenKind };
    } catch {
      return null;
    }
  }

  try {
    const now = new Date().toISOString();
    const accessEnc = await encryptTikTokContentToken(refreshed.access_token);
    const refreshEnc = refreshed.refresh_token
      ? await encryptTikTokContentToken(refreshed.refresh_token)
      : String(tokenRow.refresh_token_enc);
    const accessExpires = refreshed.expires_in
      ? new Date(Date.now() + refreshed.expires_in * 1000).toISOString()
      : tokenRow.access_token_expires_at;

    const resolvedScopes = mergeTikTokContentOAuthScopes(
      tokenRow.oauth_scopes,
      refreshed.scope,
      TIKTOK_CONTENT_OAUTH_SCOPES,
    );

    await admin.from("organization_tiktok_content_connection_tokens").update({
      access_token_enc: accessEnc,
      refresh_token_enc: refreshEnc,
      access_token_expires_at: accessExpires,
      oauth_scopes: resolvedScopes,
      updated_at: now,
    }).eq("organization_id", organizationId).eq("open_id", openId);
  } catch (e) {
    console.error("getTikTokContentAccessToken persist refresh:", e);
  }

  return { accessToken: refreshed.access_token, tokenKind };
}

export async function getTikTokPublishAccessToken(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
): Promise<string | null> {
  const { data: row } = await admin
    .from("organization_tiktok_content_connection_tokens")
    .select(
      "access_token_enc, refresh_token_enc, access_token_expires_at, oauth_token_kind, publish_access_token_enc, publish_refresh_token_enc, publish_access_token_expires_at, publish_oauth_scopes, oauth_scopes",
    )
    .eq("organization_id", organizationId)
    .eq("open_id", openId)
    .maybeSingle();
  if (!row) return null;

  const tokenRow = row as TokenRow;
  const tokenKind = normalizeTokenKind(tokenRow.oauth_token_kind);
  const hasPublishVault = Boolean(tokenRow.publish_access_token_enc && tokenRow.publish_refresh_token_enc);

  const publishExpiresAtMs = tokenRow.publish_access_token_expires_at
    ? new Date(String(tokenRow.publish_access_token_expires_at)).getTime()
    : null;
  const publishNeedsRefresh = hasPublishVault &&
    publishExpiresAtMs != null &&
    Number.isFinite(publishExpiresAtMs) &&
    publishExpiresAtMs < Date.now() + 60_000;

  if (hasPublishVault && !publishNeedsRefresh) {
    try {
      return await decryptTikTokContentToken(String(tokenRow.publish_access_token_enc));
    } catch (e) {
      console.error("getTikTokPublishAccessToken decrypt publish:", e);
    }
  }

  if (hasPublishVault && publishNeedsRefresh) {
    const publishOAuth = readPlatformTikTokContentPublishOAuth() ?? readPlatformTikTokContentOAuth();
    if (publishOAuth) {
      try {
        const refreshToken = await decryptTikTokContentToken(
          String(tokenRow.publish_refresh_token_enc),
        );
        const refreshed = await refreshTikTokContentAccessToken(
          publishOAuth.clientKey,
          publishOAuth.clientSecret,
          refreshToken,
        );
        if (refreshed?.access_token) {
          const now = new Date().toISOString();
          const accessEnc = await encryptTikTokContentToken(refreshed.access_token);
          const refreshEnc = refreshed.refresh_token
            ? await encryptTikTokContentToken(refreshed.refresh_token)
            : String(tokenRow.publish_refresh_token_enc);
          const accessExpires = refreshed.expires_in
            ? new Date(Date.now() + refreshed.expires_in * 1000).toISOString()
            : tokenRow.publish_access_token_expires_at;
          const publishScopes = mergeTikTokContentOAuthScopes(
            tokenRow.publish_oauth_scopes,
            refreshed.scope,
            TIKTOK_CONTENT_OAUTH_SCOPES,
          );
          await admin.from("organization_tiktok_content_connection_tokens").update({
            publish_access_token_enc: accessEnc,
            publish_refresh_token_enc: refreshEnc,
            publish_access_token_expires_at: accessExpires,
            publish_oauth_scopes: publishScopes,
            updated_at: now,
          }).eq("organization_id", organizationId).eq("open_id", openId);
          return refreshed.access_token;
        }
      } catch (e) {
        console.error("getTikTokPublishAccessToken refresh publish:", e);
      }
    }
    try {
      return await decryptTikTokContentToken(String(tokenRow.publish_access_token_enc));
    } catch {
      /* fall through */
    }
  }

  if (tokenKind === TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.loginKit) {
    const primary = await getTikTokContentAccessToken(admin, organizationId, openId);
    return primary?.accessToken ?? null;
  }

  return null;
}

export async function resolveOrgTikTokContentForMetrics(
  admin: SupabaseClient,
  organizationId: string,
  openIdParam?: string | null,
): Promise<{
  accessToken: string;
  account: TikTokContentAccountRow;
  tokenKind: TikTokContentOAuthTokenKind;
} | null> {
  let account: TikTokContentAccountRow | null = null;

  if (openIdParam) {
    const { data: row } = await admin
      .from("organization_tiktok_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .eq("open_id", openIdParam.trim())
      .maybeSingle();
    if (row) account = row as TikTokContentAccountRow;
  }

  if (!account) {
    const { data: defaultRow } = await admin
      .from("organization_tiktok_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .eq("is_default", true)
      .maybeSingle();
    account = (defaultRow as TikTokContentAccountRow | null) ?? null;
  }

  if (!account) {
    const { data: firstRow } = await admin
      .from("organization_tiktok_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .order("sort_order", { ascending: true })
      .limit(1)
      .maybeSingle();
    account = (firstRow as TikTokContentAccountRow | null) ?? null;
  }

  if (!account?.open_id) return null;

  const tokenResult = await getTikTokContentAccessToken(admin, organizationId, account.open_id);
  if (!tokenResult) return null;

  return {
    accessToken: tokenResult.accessToken,
    account,
    tokenKind: tokenResult.tokenKind,
  };
}

/**
 * AES-256-GCM for TikTok Content OAuth tokens.
 * Reuses TIKTOK_ADS_CONFIG_ENCRYPTION_KEY (or TIKTOK_CONTENT_CONFIG_ENCRYPTION_KEY).
 */

const ALGO = "AES-GCM";
const IV_LEN = 12;
const TAG_LEN = 128;

function decodeKey(raw: string): Uint8Array {
  const trimmed = raw.trim();
  if (!trimmed) throw new Error("Encryption key is not set");
  if (/^[0-9a-fA-F]{64}$/.test(trimmed)) {
    const bytes = new Uint8Array(32);
    for (let i = 0; i < 32; i++) {
      bytes[i] = parseInt(trimmed.slice(i * 2, i * 2 + 2), 16);
    }
    return bytes;
  }
  const bin = atob(trimmed);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  if (bytes.length !== 32) {
    throw new Error("Encryption key must be 32 bytes (base64 or 64-char hex)");
  }
  return bytes;
}

function getKeyBytes(): Uint8Array {
  const raw = Deno.env.get("TIKTOK_CONTENT_CONFIG_ENCRYPTION_KEY")?.trim() ??
    Deno.env.get("TIKTOK_ADS_CONFIG_ENCRYPTION_KEY") ?? "";
  return decodeKey(raw);
}

function toBase64(bytes: Uint8Array): string {
  let s = "";
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}

function fromBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function encrypt(plaintext: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const iv = crypto.getRandomValues(new Uint8Array(IV_LEN));
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["encrypt"]);
  const enc = await crypto.subtle.encrypt(
    { name: ALGO, iv, tagLength: TAG_LEN },
    key,
    new TextEncoder().encode(plaintext),
  );
  const combined = new Uint8Array(iv.length + enc.byteLength);
  combined.set(iv, 0);
  combined.set(new Uint8Array(enc), iv.length);
  return toBase64(combined);
}

async function decrypt(ciphertextB64: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const combined = fromBase64(ciphertextB64.trim());
  if (combined.length < IV_LEN + 16) throw new Error("Invalid encrypted token payload");
  const iv = combined.slice(0, IV_LEN);
  const data = combined.slice(IV_LEN);
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["decrypt"]);
  const dec = await crypto.subtle.decrypt({ name: ALGO, iv, tagLength: TAG_LEN }, key, data);
  return new TextDecoder().decode(dec);
}

export async function encryptTikTokContentToken(plaintext: string): Promise<string> {
  return encrypt(plaintext);
}

export async function decryptTikTokContentToken(ciphertextB64: string): Promise<string> {
  return decrypt(ciphertextB64);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import type { TikTokVideoRow } from "./tiktokContentApi.ts";

export type PlanMatchInfo = {
  plan_id: string | null;
  service_name: string | null;
  content_pillar: string | null;
  pic_name: string | null;
  actual_post_date: string | null;
  match_type: "share_url" | "video_id" | null;
  link_id: string | null;
};

type LinkRow = {
  id: string;
  url: string;
  external_post_id: string | null;
  social_media_plan_id: string;
};

type PlanRow = {
  id: string;
  actual_post_date: string | null;
  pic_id: string | null;
  service_id: string | null;
  content_pillar_id: string | null;
  services?: { name?: string } | { name?: string }[] | null;
  content_pillars?: { name?: string } | { name?: string }[] | null;
  employees?: { full_name?: string } | { full_name?: string }[] | null;
};

export function parseTikTokVideoIdFromUrl(url: string): string | null {
  const trimmed = url.trim();
  if (!trimmed) return null;
  const patterns = [
    /\/video\/(\d+)/i,
    /tiktok\.com\/@[^/]+\/video\/(\d+)/i,
    /vm\.tiktok\.com\/(\w+)/i,
  ];
  for (const re of patterns) {
    const m = re.exec(trimmed);
    if (m?.[1] && /^\d+$/.test(m[1])) return m[1];
  }
  return null;
}

function normalizeUrl(url: string): string {
  try {
    const u = new URL(url.trim());
    u.search = "";
    u.hash = "";
    return u.toString().replace(/\/+$/, "");
  } catch {
    return url.trim().replace(/\/+$/, "");
  }
}

function pickName(rel: { name?: string } | { name?: string }[] | null | undefined): string | null {
  if (!rel) return null;
  if (Array.isArray(rel)) return rel[0]?.name ? String(rel[0].name) : null;
  return rel.name ? String(rel.name) : null;
}

function pickEmployeeName(
  rel: { full_name?: string } | { full_name?: string }[] | null | undefined,
): string | null {
  if (!rel) return null;
  if (Array.isArray(rel)) return rel[0]?.full_name ? String(rel[0].full_name) : null;
  return rel.full_name ? String(rel.full_name) : null;
}

export async function loadTikTokPlanLinks(
  admin: SupabaseClient,
  organizationId: string,
): Promise<LinkRow[]> {
  const { data: links } = await admin
    .from("social_media_links")
    .select("id, url, external_post_id, social_media_plan_id, platform")
    .ilike("platform", "tiktok");

  const rows = (links ?? []).filter((l) => {
    const platform = String((l as { platform?: string }).platform ?? "").toLowerCase();
    return platform.includes("tiktok");
  }) as LinkRow[];

  if (rows.length === 0) return [];

  const planIds = [...new Set(rows.map((r) => r.social_media_plan_id))];
  const { data: plans } = await admin
    .from("social_media_plans")
    .select("id, organization_id")
    .eq("organization_id", organizationId)
    .in("id", planIds);

  const orgPlanSet = new Set((plans ?? []).map((p) => String((p as { id: string }).id)));
  return rows.filter((r) => orgPlanSet.has(r.social_media_plan_id));
}

export function buildPlanMatchIndex(links: LinkRow[]): {
  byVideoId: Map<string, LinkRow>;
  byShareUrl: Map<string, LinkRow>;
} {
  const byVideoId = new Map<string, LinkRow>();
  const byShareUrl = new Map<string, LinkRow>();
  for (const link of links) {
    const vid = link.external_post_id?.trim() || parseTikTokVideoIdFromUrl(link.url);
    if (vid) byVideoId.set(vid, link);
    byShareUrl.set(normalizeUrl(link.url), link);
  }
  return { byVideoId, byShareUrl };
}

export async function loadPlanDetails(
  admin: SupabaseClient,
  planIds: string[],
): Promise<Map<string, PlanRow>> {
  if (planIds.length === 0) return new Map();
  const { data } = await admin
    .from("social_media_plans")
    .select(`
      id,
      actual_post_date,
      pic_id,
      service_id,
      content_pillar_id,
      services ( name ),
      content_pillars ( name )
    `)
    .in("id", planIds);

  const picIds = [...new Set((data ?? []).map((r) => (r as PlanRow).pic_id).filter(Boolean))];
  const picNameById = new Map<string, string>();
  if (picIds.length > 0) {
    const { data: employees } = await admin
      .from("employees")
      .select("id, full_name")
      .in("id", picIds as string[]);
    for (const e of employees ?? []) {
      const id = String((e as { id: string }).id);
      const name = String((e as { full_name?: string }).full_name ?? "").trim();
      if (name) picNameById.set(id, name);
    }
  }

  const map = new Map<string, PlanRow>();
  for (const row of data ?? []) {
    const plan = row as PlanRow;
    const picId = plan.pic_id != null ? String(plan.pic_id) : "";
    if (picId && picNameById.has(picId)) {
      plan.employees = { full_name: picNameById.get(picId) };
    }
    map.set(String(plan.id), plan);
  }
  return map;
}

export function matchVideoToPlan(
  video: TikTokVideoRow,
  index: { byVideoId: Map<string, LinkRow>; byShareUrl: Map<string, LinkRow> },
  planMap: Map<string, PlanRow>,
): PlanMatchInfo {
  const videoId = String(video.id ?? "").trim();
  const shareUrl = video.share_url ? normalizeUrl(video.share_url) : "";

  let link: LinkRow | undefined;
  let matchType: PlanMatchInfo["match_type"] = null;

  if (shareUrl && index.byShareUrl.has(shareUrl)) {
    link = index.byShareUrl.get(shareUrl);
    matchType = "share_url";
  } else if (videoId && index.byVideoId.has(videoId)) {
    link = index.byVideoId.get(videoId);
    matchType = "video_id";
  }

  if (!link) {
    return {
      plan_id: null,
      service_name: null,
      content_pillar: null,
      pic_name: null,
      actual_post_date: null,
      match_type: null,
      link_id: null,
    };
  }

  const plan = planMap.get(link.social_media_plan_id);
  return {
    plan_id: link.social_media_plan_id,
    service_name: pickName(plan?.services ?? null),
    content_pillar: pickName(plan?.content_pillars ?? null),
    pic_name: pickEmployeeName(plan?.employees ?? null),
    actual_post_date: plan?.actual_post_date != null ? String(plan.actual_post_date) : null,
    match_type: matchType,
    link_id: link.id,
  };
}

export function computeEngagementRate(video: TikTokVideoRow): number | null {
  const views = Number(video.view_count ?? 0);
  if (!Number.isFinite(views) || views <= 0) return null;
  const likes = Number(video.like_count ?? 0) || 0;
  const comments = Number(video.comment_count ?? 0) || 0;
  const shares = Number(video.share_count ?? 0) || 0;
  return ((likes + comments + shares) / views) * 100;
}

export async function backfillLinkVideoIds(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
  matches: Array<{ link_id: string; video_id: string }>,
): Promise<void> {
  const now = new Date().toISOString();
  for (const m of matches) {
    await admin
      .from("social_media_links")
      .update({
        external_post_id: m.video_id,
        platform_account_open_id: openId,
        last_insights_sync_at: now,
      })
      .eq("id", m.link_id);
  }
}
